[
    {
        "title": "读懂角度比",
        "description": "已知三角形三个内角的度数比是 $1:3:5$，说明这三个角可以分别看成 $1$ 份、$3$ 份、$5$ 份。",
        "bubbleText": "看到“角度之比”，先别急着算，先把三个角想成按份数分配：一个最小， 一个中等， 一个最大。",
        "bubblePos": {
            "x": 244,
            "y": 255
        }
    },
    {
        "title": "设每份为x",
        "description": "设每一份是 $x$ 度，则 $\\angle D=x$，$\\angle E=3x$，$\\angle F=5x$。",
        "bubbleText": "按比例题最常用的方法就是“设份数”。这样原来的比就变成了真正的角度表达式。",
        "bubblePos": {
            "x": 385,
            "y": 360
        }
    },
    {
        "title": "利用内角和",
        "description": "因为三角形内角和是 $180^\\circ$，所以\\n$\\angle D+\\angle E+\\angle F=180^\\circ$，\\n即 $x+3x+5x=180^\\circ$。",
        "bubbleText": "三个角都在同一个三角形里，所以它们加起来一定是 $180^\\circ$，这是关键条件。",
        "bubblePos": {
            "x": 304,
            "y": 485
        }
    },
    {
        "title": "求出x",
        "description": "合并同类项得 $9x=180^\\circ$，所以 $x=20^\\circ$。",
        "bubbleText": "$1x+3x+5x$ 一共是 $9x$，再用 $180\\div 9$ 就能知道一份是多少度。",
        "bubblePos": {
            "x": 430,
            "y": 280
        }
    },
    {
        "title": "先求∠E",
        "description": "因为 $\\angle E=3x$，代入 $x=20^\\circ$，得到\\n$\\angle E=3\\times 20^\\circ=60^\\circ$。",
        "bubbleText": "题目最后要找的是和点 $E$ 有关的角，所以先把整个 $\\angle E$ 算出来最自然。",
        "bubblePos": {
            "x": 260,
            "y": 300
        }
    },
    {
        "title": "用角平分线",
        "description": "EP 平分 $\\angle DEF$，说明它把 $\\angle E$ 分成两个相等的角，所以\\n$\\angle DEP=\\frac{60^\\circ}{2}=30^\\circ$。",
        "bubbleText": "“平分”就是平均分成两半，所以只要把 $60^\\circ$ 除以 $2$ 就行。",
        "bubblePos": {
            "x": 300,
            "y": 455
        }
    },
    {
        "title": "检查是否合理",
        "description": "验证：若 $\\angle DEP=30^\\circ$，则另一半 $\\angle PEF$ 也应是 $30^\\circ$，两部分相加正好是 $60^\\circ$，与 $\\angle E$ 一致，说明结果正确。",
        "bubbleText": "检查时看两半是不是一样大，而且加起来是不是原来的整个角，这样最稳妥。",
        "bubblePos": {
            "x": 315,
            "y": 268
        }
    },
    {
        "title": "写出答案",
        "description": "因此，$\\angle DEP=30^\\circ$。",
        "bubbleText": "先用角度比求出整个角，再用角平分线除以 $2$，答案就是 $30^\\circ$。",
        "bubblePos": {
            "x": 420,
            "y": 560
        }
    }
]
